const uint32_t platform_uds_dtcs[PLATFORM_UDS_DTC_COUNT] = {
    PLATFORM_UDS_DTC_VEHICLE_ECU_COMM_LOST,
    PLATFORM_UDS_DTC_VEHICLE_TESTER_LATCHED,
    PLATFORM_UDS_DTC_VEHICLE_BUS_OFF_LATCHED,
};

const platform_uds_did_t *platform_uds_find_did(uint16_t did)
{
    size_t i;

    for (i = 0u; i < PLATFORM_UDS_DID_COUNT; i++) {
        if (platform_uds_dids[i].did == did) {
            return &platform_uds_dids[i];
        }
    }
    return NULL;
}

bool platform_uds_service_supported(uint8_t sid)
{
    bool ok;

    switch (sid) {
    case 0x10u: /* DIAGNOSTIC_SESSION_CONTROL */
    case 0x3Eu: /* TESTER_PRESENT */
    case 0x22u: /* READ_DATA_BY_IDENTIFIER */
    case 0x19u: /* READ_DTC_INFORMATION */
    case 0x14u: /* CLEAR_DIAGNOSTIC_INFORMATION */
        ok = true;
        break;
    default:
        ok = false;
        break;
    }
    return ok;
}

bool platform_uds_service_allowed_in_session(uint8_t sid, uint8_t session)
{
    bool ok;

    switch (sid) {
    case 0x10u: /* DIAGNOSTIC_SESSION_CONTROL */
        ok = (session == 0x01u) || (session == 0x03u);
        break;
    case 0x3Eu: /* TESTER_PRESENT */
        ok = (session == 0x01u) || (session == 0x03u);
        break;
    case 0x22u: /* READ_DATA_BY_IDENTIFIER */
        ok = (session == 0x01u) || (session == 0x03u);
        break;
    case 0x19u: /* READ_DTC_INFORMATION */
        ok = (session == 0x01u) || (session == 0x03u);
        break;
    case 0x14u: /* CLEAR_DIAGNOSTIC_INFORMATION */
        ok = (session == 0x03u);
        break;
    default:
        ok = false;
        break;
    }
    return ok;
}

bool platform_uds_session_supported(uint8_t session)
{
    return (session == 0x01u) || (session == 0x03u);
}

bool platform_uds_subfunction_supported(uint8_t sid, uint8_t subfunction)
{
    uint8_t sub = (uint8_t)(subfunction & 0x7Fu); /* suppressPosRsp bit */
    bool ok;

    switch (sid) {
    case 0x3Eu: /* TESTER_PRESENT */
        ok = (sub == 0x00u);
        break;
    case 0x19u: /* READ_DTC_INFORMATION */
        ok = (sub == 0x01u) || (sub == 0x02u) || (sub == 0x0Au);
        break;
    default:
        ok = false;
        break;
    }
    return ok;
}

bool platform_uds_nrc_suppressed_functional(uint8_t nrc)
{
    return (nrc == 0x11u) || (nrc == 0x12u) || (nrc == 0x31u) || (nrc == 0x7Eu) || (nrc == 0x7Fu);
}
